export function getRoster2027ForTeam(teamCode: string): Player[] {
  let roster = NBA_ROSTERS_2027[teamCode];
  if (!roster) {
    const names = SEEDS_2027[teamCode] || [];
    const positions: Array<'PG' | 'SG' | 'SF' | 'PF' | 'C'> = ['PG', 'SG', 'SF', 'PF', 'C', 'PG', 'SG', 'SF', 'PF', 'C'];
    
    roster = names.map((name, i) => {
      const tier = i === 0 ? 1 : i < 3 ? 2 : i < 6 ? 3 : 4;
      const basePpg = tier === 1 ? 25.8 : tier === 2 ? 19.2 : tier === 3 ? 12.8 : 7.2;
      const baseRpg = positions[i] === 'C' ? 9.8 : positions[i] === 'PF' ? 7.2 : 4.0;
      const baseApg = positions[i] === 'PG' ? 7.0 : positions[i] === 'SG' ? 4.0 : 2.2;
      const baseFgPct = positions[i] === 'C' ? 59.2 : 46.8;
      const baseTpPct = positions[i] === 'C' ? 24.0 : 38.5;
      const basePer = tier === 1 ? 24.8 : tier === 2 ? 19.0 : tier === 3 ? 15.0 : 12.0;
      const baseMinutes = tier === 1 ? 34.8 : tier === 2 ? 31.5 : tier === 3 ? 25.0 : 16.5;

      // Check if known transferred player
      const isKnownTransfer = ['Josh Giddey', 'DeMar DeRozan', 'Deni Avdija', 'Dejounte Murray', 'Gary Trent Jr.', 'Zach Edey', 'Ace Bailey', 'Tobias Harris'].includes(name);

      return {
        id: `${teamCode.toLowerCase()}-27-${i + 1}`,
        name,
        teamCode,
        position: positions[i],
        number: (i * 7 + 3) % 99,
        basePpg,
        baseRpg,
        baseApg,
        baseFgPct,
        baseTpPct,
        basePer,
        baseMinutes,
        isTransferred: isKnownTransfer,
        transferNote: isKnownTransfer ? `Incorporación confirmada para la temporada 2026-2027` : undefined,
        priorTeamCode: teamCode,
        priorPpg: Math.round(basePpg * 0.96 * 10) / 10,
        priorRpg: baseRpg,
        priorApg: baseApg,
        priorPer: Math.round(basePer * 0.96 * 10) / 10,
        priorMinutes: baseMinutes,
        priorFgPct: baseFgPct,
        priorTpPct: baseTpPct
      };
    });
    NBA_ROSTERS_2027[teamCode] = roster;
  }
  return roster;
}
